import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  // Create plane geometry with aspect ratio matching atlas texture (512:320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load brushed metal texture
  const textureUrl = config.assets?.imageUrl || '/prism-assets/chrome/brushed-metal.map.png';
  const texture = ctx.textureLoader.load(textureUrl);

  // Create material - MeshBasicNodeMaterial for static unlit composition
  const material = new MeshBasicNodeMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement from config
  const scenePos = config.scenePosition || { x: 3.2, y: -0.3, z: 0 };
  const sceneRot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const sceneScale = config.sceneScale || { x: 1, y: 1, z: 1 };

  mesh.position.set(scenePos.x, scenePos.y, scenePos.z);
  mesh.rotation.set(sceneRot.x, sceneRot.y, sceneRot.z);
  mesh.scale.set(sceneScale.x, sceneScale.y, sceneScale.z);

  // Apply cinematic primitives if specified
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(primitive => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](mesh, primitive.params || {});
      }
    });
  }

  // Setup cleanup function
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  // Initialize event handlers object (no interactivity for static composition)
  mesh.userData.handlers = {};

  return mesh;
}
